{"output":"1\t# -*- coding: utf-8 -*-\n2\t\"\"\"PayPal 沙箱：OAuth 换 token + 创建日元订单（intent=CAPTURE）。\n3\t\n4\t⚠️ 仅创建订单并返回 approve 链接，永不自动 approve / capture（支付须用户二次确认）。\n5\t\n6\t用法：\n7\t  PAYPAL_CLIENT_ID=.. PAYPAL_CLIENT_SECRET=.. python3 paypal_billing.py get-token\n8\t  PAYPAL_CLIENT_ID=.. PAYPAL_CLIENT_SECRET=.. python3 paypal_billing.py create-order --amount-jpy 16500 --item-name \"LYCEE POD020-LYB\"\n9\t\"\"\"\n10\timport argparse\n11\timport json\n12\t\n13\tfrom _common import load_secrets, http_request, basic_auth, JsbError\n14\t\n15\tTOKEN_URL = \"https://api-m.sandbox.paypal.com/v1/oauth2/token\"\n16\tORDERS_URL = \"https://api-m.sandbox.paypal.com/v2/checkout/orders\"\n17\t\n18\t\n19\tdef get_token(secrets=None):\n20\t    secrets = secrets or load_secrets()\n21\t    cid = secrets.get(\"PAYPAL_CLIENT_ID\")\n22\t    sec = secrets.get(\"PAYPAL_CLIENT_SECRET\")\n23\t    if not cid or not sec:\n24\t        raise JsbError(\"缺少 PayPal 凭证：请设置 PAYPAL_CLIENT_ID / PAYPAL_CLIENT_SECRET\")\n25\t\n26\t    status, text = http_request(\n27\t        \"POST\", TOKEN_URL,\n28\t        headers={\"Authorization\": basic_auth(cid, sec),\n29\t                 \"Content-Type\": \"application/x-www-form-urlencoded\"},\n30\t        body=\"grant_type=client_credentials\",\n31\t        use_proxy=False, timeout=25,\n32\t    )\n33\t    if status != 200:\n34\t        raise JsbError(f\"PayPal OAuth 失败 HTTP {status}: {text[:200]}\")\n35\t    data = json.loads(text)\n36\t    return {\n37\t        \"access_token\": data.get(\"access_token\"),\n38\t        \"token_type\": data.get(\"token_type\"),\n39\t        \"expires_in\": data.get(\"expires_in\"),\n40\t        \"scope\": data.get(\"scope\"),\n41\t    }\n42\t\n43\t\n44\tdef create_order(amount_jpy, item_name, secrets=None):\n45\t    token = get_token(secrets)[\"access_token\"]\n46\t    body = {\n47\t        \"intent\": \"CAPTURE\",\n48\t        \"purchase_units\": [{\n49\t            \"reference_id\": \"japan-shopping-buddy\",\n50\t            \"description\": item_name,\n51\t            \"amount\": {\"currency_code\": \"JPY\", \"value\": f\"{float(amount_jpy):.2f}\"},\n52\t        }],\n53\t    }\n54\t    status, text = http_request(\n55\t        \"POST\", ORDERS_URL,\n56\t        headers={\"Authorization\": f\"Bearer {token}\",\n57\t                 \"Content-Type\": \"application/json\",\n58\t                 \"Prefer\": \"return=representation\"},\n59\t        body=json.dumps(body),\n60\t        use_proxy=False, timeout=25,\n61\t    )\n62\t    if status not in (200, 201):\n63\t        raise JsbError(f\"PayPal Orders 失败 HTTP {status}: {text[:200]}\")\n64\t    data = json.loads(text)\n65\t    approve = next((l[\"href\"] for l in data.get(\"links\", []) if l.get(\"rel\") == \"approve\"), None)\n66\t    return {\n67\t        \"order_id\": data.get(\"id\"),\n68\t        \"status\": data.get(\"status\"),\n69\t        \"amount\": {\"currency_code\": \"JPY\", \"value\": f\"{float(amount_jpy):.2f}\"},\n70\t        \"item_name\": item_name,\n71\t        \"approve_link\": approve,\n72\t        \"note\": \"订单已创建（未付款）。请用户点击 approve_link 完成付款；切勿自动 approve/capture。\",\n73\t    }\n74\t\n75\t\n76\tdef main():\n77\t    ap = argparse.ArgumentParser(description=\"PayPal 沙箱订单\")\n78\t    sub = ap.add_subparsers(dest=\"cmd\", required=True)\n79\t    sub.add_parser(\"get-token\")\n80\t    co = sub.add_parser(\"create-order\")\n81\t    co.add_argument(\"--amount-jpy\", type=float, required=True)\n82\t    co.add_argument(\"--item-name\", default=\"日本商品\")\n83\t    args = ap.parse_args()\n84\t\n85\t    try:\n86\t        if args.cmd == \"get-token\":\n87\t            result = get_token()\n88\t        else:\n89\t            result = create_order(args.amount_jpy, args.item_name)\n90\t    except JsbError as e:\n91\t        msg = str(e)\n92\t        if \"凭证\" in msg:\n93\t            code = \"AUTH_MISSING\"\n94\t        elif \"HTTP\" in msg:\n95\t            code = \"HTTP_ERROR\"\n96\t        else:\n97\t            code = \"RESULT_UNKNOWN\"\n98\t        print(json.dumps({\"status\": \"error\", \"code\": code, \"error\": msg},\n99\t                         ensure_ascii=False, indent=2))\n100\t        raise SystemExit(1)\n101\t\n102\t    print(json.dumps(result, ensure_ascii=False, indent=2))\n103\t\n104\t\n105\tif __name__ == \"__main__\":\n106\t    main()"}
